#include "Broadcast.hpp"
#include <chrono>
namespace noir::win {
std::wstring quoteArgument(const std::wstring& value){std::wstring out=L"\"";size_t slashes=0;for(wchar_t c:value){if(c==L'\\'){++slashes;continue;}if(c==L'\"')out.append(slashes*2+1,L'\\');else out.append(slashes,L'\\');slashes=0;out+=c;}out.append(slashes*2,L'\\');out+=L'\"';return out;}
std::vector<std::wstring> broadcastArguments(const BroadcastConfig& c){
    if(c.bus<0||c.bus>3||c.bitrate<64||c.bitrate>320)throw std::runtime_error("Choose a valid bus and bitrate");
    if(c.url.empty()||c.url.size()>4096||c.url.find_first_of(L"\r\n\t ")!=std::wstring::npos||c.url.find(L'\0')!=std::wstring::npos)throw std::runtime_error("Enter a complete streaming URL without spaces");
    if(c.icecast ? c.url.rfind(L"icecast://",0)!=0 : c.url.rfind(L"rtmp://",0)!=0&&c.url.rfind(L"rtmps://",0)!=0)throw std::runtime_error("Use an icecast:// or rtmp(s):// URL for the selected protocol");
    auto authority=c.url.substr(c.url.find(L"://")+3);if(authority.empty()||authority[0]==L'/'||authority.find(L'/')==std::wstring::npos)throw std::runtime_error("Streaming URL needs a host and mount or stream key");
    std::vector<std::wstring> a{L"-hide_banner",L"-loglevel",L"error",L"-nostdin",L"-f",L"f32le",L"-ar",L"48000",L"-ac",L"2",L"-i",L"pipe:0",L"-vn",L"-c:a",c.icecast?L"libmp3lame":L"aac",L"-b:a",std::to_wstring(c.bitrate)+L"k",L"-rw_timeout",L"8000000"};
    if(c.icecast){a.insert(a.end(),{L"-content_type",L"audio/mpeg",L"-ice_name",L"NOIR Audio",L"-tls",c.tls?L"1":L"0"});if(c.tls)a.insert(a.end(),{L"-tls_verify",L"1"});}
    else if(c.url.rfind(L"rtmps://",0)==0)a.insert(a.end(),{L"-tls_verify",L"1"});
    a.insert(a.end(),{L"-f",c.icecast?L"mp3":L"flv",c.url});return a;
}
void Broadcaster::status(std::string s){std::lock_guard lock(mutex);message=std::move(s);}std::string Broadcaster::status()const{std::lock_guard lock(mutex);return message;}
void Broadcaster::start(BroadcastConfig c){stop();auto args=broadcastArguments(c);if(!std::filesystem::is_regular_file(c.encoder)||std::filesystem::path(c.encoder).extension()!=L".exe")throw std::runtime_error("Choose a local ffmpeg.exe first");ResetEvent(cancelled.get());active=true;frames=0;status("Connecting encoder…");thread=std::thread([this,c]{run(c);});}
void Broadcaster::stop(){requestStop();if(thread.joinable())thread.join();active=false;core.broadcastEnabled=false;}
void Broadcaster::run(BroadcastConfig c){Handle process,processThread,job;try{
    auto pipeName=L"\\\\.\\pipe\\NOIR-"+guidName();Handle pipe(CreateNamedPipeW(pipeName.c_str(),PIPE_ACCESS_OUTBOUND|FILE_FLAG_OVERLAPPED|FILE_FLAG_FIRST_PIPE_INSTANCE,PIPE_TYPE_BYTE|PIPE_WAIT|PIPE_REJECT_REMOTE_CLIENTS,1,65536,65536,0,nullptr));if(!pipe)throw std::runtime_error("Cannot create encoder pipe");
    SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};Handle input(CreateFileW(pipeName.c_str(),GENERIC_READ,0,&sa,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr));Handle sink(CreateFileW(L"NUL",GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,&sa,OPEN_EXISTING,0,nullptr));if(!input||!sink)throw std::runtime_error("Cannot connect encoder pipe");
    STARTUPINFOEXW si{};si.StartupInfo.cb=sizeof(si);si.StartupInfo.dwFlags=STARTF_USESTDHANDLES;si.StartupInfo.hStdInput=input.get();si.StartupInfo.hStdOutput=si.StartupInfo.hStdError=sink.get();SIZE_T bytes=0;InitializeProcThreadAttributeList(nullptr,1,0,&bytes);std::vector<uint8_t> storage(bytes);si.lpAttributeList=reinterpret_cast<LPPROC_THREAD_ATTRIBUTE_LIST>(storage.data());if(!InitializeProcThreadAttributeList(si.lpAttributeList,1,0,&bytes))throw std::runtime_error("Cannot initialize encoder process");
    struct Attributes {LPPROC_THREAD_ATTRIBUTE_LIST p;~Attributes(){DeleteProcThreadAttributeList(p);}} attributes{si.lpAttributeList};HANDLE inherited[]={input.get(),sink.get()};if(!UpdateProcThreadAttribute(si.lpAttributeList,0,PROC_THREAD_ATTRIBUTE_HANDLE_LIST,inherited,sizeof(inherited),nullptr,nullptr))throw std::runtime_error("Cannot isolate encoder handles");
    job.reset(CreateJobObjectW(nullptr,nullptr));JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits{};limits.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;if(!job||!SetInformationJobObject(job.get(),JobObjectExtendedLimitInformation,&limits,sizeof(limits)))throw std::runtime_error("Cannot supervise encoder process");
    std::wstring command=quoteArgument(c.encoder);for(auto& a:broadcastArguments(c))command+=L" "+quoteArgument(a);PROCESS_INFORMATION pi{};BOOL created=CreateProcessW(c.encoder.c_str(),command.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW|CREATE_SUSPENDED|EXTENDED_STARTUPINFO_PRESENT,nullptr,std::filesystem::path(c.encoder).parent_path().c_str(),&si.StartupInfo,&pi);SecureZeroMemory(command.data(),command.size()*sizeof(wchar_t));if(!created)throw std::runtime_error("Could not launch ffmpeg.exe");process.reset(pi.hProcess);processThread.reset(pi.hThread);if(!AssignProcessToJobObject(job.get(),process.get())){TerminateProcess(process.get(),1);throw std::runtime_error("Cannot supervise encoder process");}ResumeThread(processThread.get());input.reset();sink.reset();
    Stereo stale;while(core.broadcastRing.pop(stale)){}core.broadcastBus=c.bus;core.broadcastEnabled=true;status("Sending audio to encoder (server acceptance is not confirmed)");Handle ready(CreateEventW(nullptr,TRUE,FALSE,nullptr));std::array<Stereo,1024> audio{};
    while(WaitForSingleObject(cancelled.get(),0)!=WAIT_OBJECT_0){if(WaitForSingleObject(process.get(),0)==WAIT_OBJECT_0)throw std::runtime_error("Encoder exited. Check the server, credentials and encoder build, then reconnect.");size_t n=0;while(n<audio.size()&&core.broadcastRing.pop(audio[n]))++n;if(!n){WaitForSingleObject(cancelled.get(),5);continue;}
        OVERLAPPED op{};op.hEvent=ready.get();ResetEvent(ready.get());DWORD written=0;BOOL ok=WriteFile(pipe.get(),audio.data(),DWORD(n*sizeof(Stereo)),&written,&op);if(!ok&&GetLastError()==ERROR_IO_PENDING){HANDLE waits[]={cancelled.get(),process.get(),ready.get()};DWORD result=WaitForMultipleObjects(3,waits,FALSE,1500);if(result!=WAIT_OBJECT_0+2){CancelIoEx(pipe.get(),&op);GetOverlappedResult(pipe.get(),&op,&written,TRUE);if(result==WAIT_OBJECT_0)break;throw std::runtime_error("Encoder stalled or disconnected; broadcast stopped");}ok=GetOverlappedResult(pipe.get(),&op,&written,FALSE);}if(!ok||written!=n*sizeof(Stereo))throw std::runtime_error("Encoder pipe closed; broadcast stopped");frames+=n;
    }
    core.broadcastEnabled=false;pipe.reset();if(WaitForSingleObject(process.get(),1500)==WAIT_TIMEOUT)TerminateJobObject(job.get(),1);status("Offline");
}catch(const std::exception&e){core.broadcastEnabled=false;if(job)TerminateJobObject(job.get(),1);status(e.what());}active=false;}
}
